mapper.sql:
FROM generation_history h
LEFT JOIN data_file d ON h.data_id = d.data_id
WHERE h.user_id = #{userId}

    AND (h.generation_description LIKE CONCAT('%', #{search}, '%')
         OR d.data_name LIKE CONCAT('%', #{search}, '%'))


    AND h.generation_time >= #{startTime}


    AND h.generation_time <= #{endTime}

mapper.select:
SELECT 

ORDER BY h.history_id DESC
LIMIT #{limit} OFFSET #{offset}
